window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8ef22d51659555e9"]={"versions": [{"id": "FIG-8ef22d51659555e9", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Profildiagramm bzw. Metamodell-Erweiterungsdiagramm im Kontext des AUTOSAR Template Modeling Guide. Das Diagramm spezifiziert die Definition des Profil-Stereotyps <code>atpClass</code> zur Erweiterung des Standard-UML-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Enthaltene Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li>Metaklasse: <code>Kernel::Class</code> mit dem Stereotyp <code>«metaclass»</code> und der Qualifizierung <code>Classifier</code> oben rechts im Namensfach.\n</li><li>Stereotyp: <code>atpClass</code>, gekennzeichnet durch das Profil-Stereotyp-Icon (zwei geschweifte Klammern) in der rechten oberen Ecke des Namensfachs.\n</li><li>Beziehung: Gerichtete Pfeilverbindung mit geschlossenem/offenem Pfeilkopf von <code>atpClass</code> zu <code>Kernel::Class</code>, annotiert mit dem Stereotyp <code>«extends»</code> und der Eigenschaftsbeschränkung <code>{required}</code>. Dies definiert eine obligatorische Erweiterungsbeziehung (Extension) der UML-Metaklasse <code>Kernel::Class</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es liegen keine Laufzeit- oder Sequenzabläufe vor. Es definiert die metamodellierte Erweiterungssemantik bei der Instanziierung von Modellklassen im Rahmen von AUTOSAR-Vorlagen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Modellierungswerkzeuge und Metamodell-Entwickler:</p>\n<ul class=\"fig-list\"><li>Das Stereotyp <code>atpClass</code> muss auf Instanzen von <code>Kernel::Class</code> angewendet werden, sobald diese den AUTOSAR-Vorlagenkonventionen für Klassen entsprechen.\n</li><li>Durch die Modifikatoren <code>«extends»</code> und <code>{required}</code> ist die Erweiterung verbindlich; jede betroffene Klasse im AUTOSAR-UML-Profil muss das Stereotyp tragen bzw. damit assoziiert sein.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4e7474a820cf7c32", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Profildiagramm bzw. Metamodell-Erweiterungsdiagramm im Kontext des AUTOSAR Template Modeling Guide. Das Diagramm spezifiziert die Definition des Profil-Stereotyps <code>atpClass</code> zur Erweiterung des Standard-UML-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Enthaltene Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li>Metaklasse: <code>Kernel::Class</code> mit dem Stereotyp <code>«metaclass»</code> und der Qualifizierung <code>Classifier</code> oben rechts im Namensfach.\n</li><li>Stereotyp: <code>atpClass</code>, gekennzeichnet durch das Profil-Stereotyp-Icon (zwei geschweifte Klammern) in der rechten oberen Ecke des Namensfachs.\n</li><li>Beziehung: Gerichtete Pfeilverbindung mit geschlossenem/offenem Pfeilkopf von <code>atpClass</code> zu <code>Kernel::Class</code>, annotiert mit dem Stereotyp <code>«extends»</code> und der Eigenschaftsbeschränkung <code>{required}</code>. Dies definiert eine obligatorische Erweiterungsbeziehung (Extension) der UML-Metaklasse <code>Kernel::Class</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es liegen keine Laufzeit- oder Sequenzabläufe vor. Es definiert die metamodellierte Erweiterungssemantik bei der Instanziierung von Modellklassen im Rahmen von AUTOSAR-Vorlagen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Modellierungswerkzeuge und Metamodell-Entwickler:</p>\n<ul class=\"fig-list\"><li>Das Stereotyp <code>atpClass</code> muss auf Instanzen von <code>Kernel::Class</code> angewendet werden, sobald diese den AUTOSAR-Vorlagenkonventionen für Klassen entsprechen.\n</li><li>Durch die Modifikatoren <code>«extends»</code> und <code>{required}</code> ist die Erweiterung verbindlich; jede betroffene Klasse im AUTOSAR-UML-Profil muss das Stereotyp tragen bzw. damit assoziiert sein.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8ef22d51659555e9", "to": "FIG-4e7474a820cf7c32", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
